export const NeuronectionMark = React.forwardRef<SVGSVGElement, LogoProps>(function NeuronectionMark(
  { size = 32, theme = 'light', title, className, width, height, ...props },
  ref,
) {
  return (
    <svg
      ref={ref}
      data-as="logo"
      data-as-logo="neuronection"
      data-as-theme={theme}
      viewBox="0 0 217 200"
      width={width ?? size}
      height={height ?? size}
      role={title ? 'img' : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn('block shrink-0', className)}
      {...props}
    >
      {title ? <title>{title}</title> : null}
      {theme === 'dark' ? DarkArt : LightArt}
    </svg>
  )
})
